3. READY-TO-TEST CODE (PHP Filter for Rank Math JSON-LD):
```php
// In /wp-content/themes/owlbethere-zee/functions.php
add_filter( 'rank_math/json_ld', function( $data, $jsonld ) {
    foreach ( $data as $key => &$entity ) {
        if ( isset( $entity['@type'] ) && $entity['@type'] === 'LocalBusiness' ) {
            $lat = get_field( 'location_latitude', 'option' );
            $lng = get_field( 'location_longitude', 'option' );
            if ( $lat && $lng ) {
                $entity['geo'] = [
                    '@type'     => 'GeoCoordinates',
                    'latitude'  => (float) $lat,
                    'longitude' => (float) $lng,
                ];
            }
            if ( empty( $entity['openingHoursSpecification'] ) ) {
                $entity['openingHoursSpecification'] = [[
                    '@type'     => 'OpeningHoursSpecification',
                    'dayOfWeek' => ['Monday','Tuesday','Wednesday','Thursday','Friday'],
                    'opens'     => '08:30',
                    'closes'    => '17:30'
                ]];
            }
        }
    }
    return $data;
}, 99, 2 );
```
